Here's a modern MSTest data-driven test class for your `PriceCalculator`:

```csharp
[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // --- DataRow: inline values for simple cases ---

    [TestMethod]
    [DataRow(100.0, 2, 200.0)]
    [DataRow(9.99, 1, 9.99)]
    [DataRow(0.0, 5, 0.0)]
    [DataRow(49.95, 0, 0.0, DisplayName = "Zero quantity returns zero")]
    public void CalculateTotal_WithQuantityAndPrice_ReturnsExpected(
        double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData with ValueTuples (preferred for complex/decimal data) ---

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithVariousInputs_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (80m, 100, 0m),
        (0m, 50, 0m),
    ];

    // --- Edge case: invalid discount throws ---

    [TestMethod]
    [DataRow(-1)]
    [DataRow(101)]
    public void ApplyDiscount_InvalidPercent_Throws(int discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, discountPercent));
    }
}
```

**Key points:**
- **`[DataRow]`** — best for simple inline primitives (`double` instead of `decimal` since attributes don't support `decimal` literals)
- **`[DynamicData]` with ValueTuples** — preferred for `decimal` values and complex data (MSTest 3.7+); gives type safety and named parameters
- **`sealed` class**, AAA pattern, descriptive names, `Assert.ThrowsExactly` instead of `[ExpectedException]`
- No need for `[DataTestMethod]` — `[TestMethod]` handles data rows in MSTest 3.x+

Adjust the method signatures to match your actual `PriceCalculator` API.
